```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;
use crate::aap::caps::types::Importance;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

fn importance_label(importance: Importance) -> &'static str {
    match importance {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth-a-look",
        Importance::Skip => "skip",
    }
}

fn render(digest: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest ");
    out.push_str(&digest.date);
    out.push('\n');

    for entry in digest.entries.iter().filter(|e| e.kept) {
        out.push_str("- [");
        out.push_str(importance_label(entry.importance));
        out.push_str("] ");
        out.push_str(&entry.title);
        out.push_str(" <");
        out.push_str(&entry.link);
        out.push_str(">\n");
    }

    out
}

export!(Node);
